begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email) values ('35000000-0000-4000-8000-000000000001','template1@example.invalid'),('35000000-0000-4000-8000-000000000002','template2@example.invalid'),('35000000-0000-4000-8000-000000000003','template3@example.invalid');
insert into public.households(id,name) values ('35000000-0000-4000-8000-000000000100','Template edits'),('35000000-0000-4000-8000-000000000200','Other templates');
insert into public.household_members(household_id,user_id,display_name) values ('35000000-0000-4000-8000-000000000100','35000000-0000-4000-8000-000000000001','Member 1'),('35000000-0000-4000-8000-000000000100','35000000-0000-4000-8000-000000000002','Member 2'),('35000000-0000-4000-8000-000000000200','35000000-0000-4000-8000-000000000003','Member 3');
insert into public.meal_definitions(id,household_id,name) values ('35000000-0000-4000-8000-000000000010','35000000-0000-4000-8000-000000000100','Pasta');
insert into public.meal_grocery_templates(id,household_id,meal_definition_id,name,sort_order) values ('35000000-0000-4000-8000-000000000020','35000000-0000-4000-8000-000000000100','35000000-0000-4000-8000-000000000010','Tomatoes',0);
select set_config('test.template.version',(select updated_at::text from public.meal_grocery_templates where id='35000000-0000-4000-8000-000000000020'),true);
select set_config('request.jwt.claim.sub','35000000-0000-4000-8000-000000000001',true);
set local role authenticated;
select lives_ok($$update public.meal_grocery_templates set quantity='2' where id='35000000-0000-4000-8000-000000000020' and updated_at=current_setting('test.template.version')::timestamptz$$,'first member edits the opened version');
select ok((select updated_at>current_setting('test.template.version')::timestamptz from public.meal_grocery_templates where id='35000000-0000-4000-8000-000000000020'),'version advances even within one transaction');
select set_config('request.jwt.claim.sub','35000000-0000-4000-8000-000000000002',true);
select is_empty($$update public.meal_grocery_templates set quantity='3' where id='35000000-0000-4000-8000-000000000020' and updated_at=current_setting('test.template.version')::timestamptz returning id$$,'stale partner edit cannot replace current data');
select is((select quantity from public.meal_grocery_templates where id='35000000-0000-4000-8000-000000000020'),'2','partner value is preserved');
select set_config('test.template.version',(select updated_at::text from public.meal_grocery_templates where id='35000000-0000-4000-8000-000000000020'),true);
select lives_ok($$update public.meal_grocery_templates set quantity='4' where id='35000000-0000-4000-8000-000000000020' and updated_at=current_setting('test.template.version')::timestamptz$$,'second member can save a freshly opened version');
select is((select quantity from public.meal_grocery_templates where id='35000000-0000-4000-8000-000000000020'),'4','fresh edit is saved');
select set_config('test.template.version',(select updated_at::text from public.meal_grocery_templates where id='35000000-0000-4000-8000-000000000020'),true);
update public.meal_grocery_templates set archived_at=now() where id='35000000-0000-4000-8000-000000000020';
update public.meal_grocery_templates set archived_at=null where id='35000000-0000-4000-8000-000000000020';
select is_empty($$update public.meal_grocery_templates set quantity='old draft' where id='35000000-0000-4000-8000-000000000020' and updated_at=current_setting('test.template.version')::timestamptz returning id$$,'archive and restore invalidate old drafts');
select throws_ok($$update public.meal_grocery_templates set updated_at='2000-01-01' where id='35000000-0000-4000-8000-000000000020'$$,'42501',null,'members cannot forge edit versions');
select set_config('request.jwt.claim.sub','35000000-0000-4000-8000-000000000003',true);
select is_empty($$select id from public.meal_grocery_templates where id='35000000-0000-4000-8000-000000000020'$$,'foreign members cannot read the template');
select is_empty($$update public.meal_grocery_templates set name='foreign' where id='35000000-0000-4000-8000-000000000020' returning id$$,'foreign edits remain denied');
select * from finish();
rollback;
